// ============================================================
// YOUTUBE - Transcribe and Extract
// Quatuor recu, jamais devine : provider / model / api_key / content.
// Ni require() ni process.env : interdits par le bac a sable n8n.
// ============================================================
const input = $input.first().json;
const body  = input.body || input;
const ctx   = body.context || {};

const lire = (src, ...cles) => {
  for (const c of cles) {
    const v = src && src[c];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};
const racine = (...cles) => lire(ctx, ...cles) ?? lire(body, ...cles);

const erreurs = [];

// --- la source : une URL directe OU une recherche ---
const videoUrl = racine('video_url', 'videoUrl', 'url') || '';
const query    = racine('query', 'q') || '';
if (!videoUrl && !query) erreurs.push('video_url ou query requis');

const googleApiKey = racine('google_api_key', 'youtube_api_key') || $env.GOOGLE_API_KEY || '';
if (!videoUrl && !googleApiKey) {
  erreurs.push('google_api_key requis pour la recherche YouTube (inutile si video_url est fourni)');
}

// --- transcription ---
const t = body.transcription || ctx.transcription || {};
const tProvider = String(lire(t, 'provider') || racine('provider') || 'google').toLowerCase();
const tModel    = lire(t, 'model', 'llm') || racine('model') || 'gemini-3.6-flash';
const tApiKey   = lire(t, 'api_key', 'apiKey') || racine('gemini_api_key') || $env.GEMINI_API_KEY || '';
const tContent  = lire(t, 'content', 'prompt') || '';
const operation = lire(t, 'operation') || racine('operation') || 'transcribe';

// --- extraction : FACULTATIVE. Absente => on rend le transcript brut. ---
const e = body.extraction || ctx.extraction || {};
const eContent  = lire(e, 'content', 'prompt') || racine('content', 'prompt') || '';
const extraire  = !!eContent;
const eProvider = String(lire(e, 'provider') || 'anthropic').toLowerCase();
const eModel    = lire(e, 'model', 'llm') || 'claude-sonnet-4-6';
const eApiKey   = lire(e, 'api_key', 'apiKey')
               || racine('anthropic_api_key', 'openai_api_key') || '';
const eMaxTokens = parseInt(lire(e, 'max_tokens') || 4096, 10);

if (extraire && !eApiKey) {
  erreurs.push('extraction.content fourni mais extraction.api_key manquante');
}

const prefs = body.preferences || ctx.preferences || {};
const langue = lire(prefs, 'language') || racine('language') || 'fr';

if (erreurs.length > 0) {
  return [{ json: { valid: false, statut: 400,
    error: { code: 400, message: erreurs.join(', '), status: 'BAD_REQUEST' } } }];
}

const callbackUrl = racine('callback_url') || null;
// job_id sans require('crypto') : $execution.id est unique par execution.
const jobId = racine('job_id') || (callbackUrl ? ('job_' + $execution.id + '_' + Date.now().toString(36)) : null);

return [{ json: {
  valid: true,
  video_url: videoUrl || null,
  query: query || null,
  google_api_key: googleApiKey,
  transcription: { provider: tProvider, model: tModel, api_key: tApiKey, content: tContent, operation },
  extraction: { demandee: extraire, provider: eProvider, model: eModel,
                api_key: eApiKey, content: eContent, max_tokens: eMaxTokens },
  language: langue,
  max_videos: lire(prefs, 'max_videos') || 1,
  prefer_short: lire(prefs, 'prefer_short') === true,
  n8n_webhook_url: $env.N8N_WEBHOOK_URL || 'http://localhost:5678',
  callback_url: callbackUrl,
  job_id: jobId,
  user_id: racine('user_id') || null,
} }];

const input = $input.first().json;

// Store all context needed for async processing
return [{
  json: {
    ...input,
    async_mode: true,
    job_started_at: new Date().toISOString()
  }
}];

// Idem : signature deleguee au noeud Crypto natif.
const e = $input.first().json;
const body = {
  success: false,
  job_id: e.job_id,
  status: 'failed',
  error: { code: 404, message: 'aucune video trouvee pour la requete', status: 'NO_RESULTS' },
  meta: { query: e.query || null },
};
return [{ json: { callback_url: e.callback_url, body, corps_json: JSON.stringify(body) } }];

const amont = $('Validate Input').first().json;
const input = $input.first().json;

// Voie A : URL fournie directement, aucune recherche n a eu lieu.
if (amont.video_url) {
  return [{ json: { ...amont,
    video: { id: null, title: null, channel: null, url: amont.video_url },
    video_url: amont.video_url } }];
}

// Voie B : resultat de la recherche YouTube.
const v = (input.items || [])[0];
const id = v?.id?.videoId;
if (!id) {
  return [{ json: { ...amont, valid: false, statut: 404,
    error: { code: 404, message: 'aucune video trouvee pour la requete', status: 'NO_RESULTS' } } }];
}
return [{ json: { ...amont,
  video: {
    id,
    title: v.snippet?.title,
    description: v.snippet?.description,
    channel: v.snippet?.channelTitle,
    thumbnail: v.snippet?.thumbnails?.high?.url || v.snippet?.thumbnails?.default?.url,
    url: 'https://www.youtube.com/watch?v=' + id,
    published_at: v.snippet?.publishedAt,
  },
  video_url: 'https://www.youtube.com/watch?v=' + id } }];

// Rend le transcript dans tous les cas ; l extraction est un PLUS,
// jamais une condition de succes. Cf. n8n-workflows#463 (faux succes).
const prep = $('Prepare Extraction').first().json;
const rep  = $input.first().json;

let extraction = null, extraction_erreur = null;

if (prep.faire_extraction) {
  const charge = rep.body !== undefined ? rep.body : rep;
  let statut = rep.statusCode;
  if (statut === undefined) {
    const brut = String(rep?.error?.message || rep?.message || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    statut = m ? parseInt(m[1], 10) : ((rep?.error || rep?.code) ? 502 : 200);
  }
  const texte = charge?.content || charge?.data?.content || charge?.text || '';
  if (statut >= 400 || !texte) {
    extraction_erreur = charge?.error?.message || rep?.error?.message || ('extraction en echec (statut ' + statut + ')');
  } else {
    // Si le prompt demandait du JSON, on le rend structure ; sinon texte brut.
    try { extraction = JSON.parse(texte); }
    catch (_) {
      const m = String(texte).match(/\{[\s\S]*\}/);
      try { extraction = m ? JSON.parse(m[0]) : { text: texte }; }
      catch (__) { extraction = { text: texte }; }
    }
  }
}

const ok = !prep.transcription_echec;
return [{ json: {
  success: ok,
  statut: ok ? 200 : (prep.transcription_statut || 502),
  job_id: prep.job_id,
  status: prep.callback_url ? (ok ? 'completed' : 'failed') : undefined,
  video: prep.video,
  video_url: prep.video_url,
  language: prep.language,
  transcript: prep.transcript || null,
  extraction,
  extraction_erreur,
  error: ok ? undefined : { code: prep.transcription_statut || 502,
                            message: prep.transcription_erreur || 'transcription indisponible',
                            status: 'TRANSCRIPTION_ERROR' },
  meta: {
    transcription: { provider: prep.transcription?.provider, model: prep.transcription?.model },
    extraction: prep.faire_extraction
      ? { provider: prep.extraction?.provider, model: prep.extraction?.model }
      : null,
    usage: { transcription: prep.transcription_usage },
  },
  callback_url: prep.callback_url,
  user_id: prep.user_id,
} }];

// La signature HMAC est calculee par le noeud Crypto natif qui suit :
// le bac a sable n8n interdit require(). Cf. execution 855886.
const e = $input.first().json;

const body = { success: e.success, job_id: e.job_id, status: e.status };
if (e.success) {
  body.data = { transcript: e.transcript, extraction: e.extraction, video: e.video };
  if (e.extraction_erreur) body.data.extraction_erreur = e.extraction_erreur;
} else {
  body.error = e.error;
}
body.meta = e.meta;

return [{ json: {
  callback_url: e.callback_url,
  body,
  corps_json: JSON.stringify(body),
} }];

// Construit le corps de LLM - Call Messages. Le transcript est INJECTE
// dans le prompt recu ; le prompt lui-meme n est jamais fabrique ici.
const amont = $('Extract Video Info').first().json;
const rep   = $input.first().json;
const charge = rep.body !== undefined ? rep.body : rep;

let statut = rep.statusCode;
if (statut === undefined) {
  const brut = String(rep?.error?.message || rep?.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  statut = m ? parseInt(m[1], 10) : ((rep?.error || rep?.code) ? 502 : 200);
}

const transcript = charge?.transcript || charge?.data?.transcript || '';
const echec = statut >= 400 || !transcript;

const ex = amont.extraction || {};
const prompt = String(ex.content || '')
  .replace(/\{\{\s*transcript\s*\}\}/g, transcript)
  .replace(/\{\{\s*title\s*\}\}/g, amont.video?.title || '')
  .replace(/\{\{\s*url\s*\}\}/g, amont.video_url || '');
const promptFinal = prompt.includes(transcript) || !transcript
  ? prompt
  : prompt + '\n\n--- Transcript ---\n' + transcript;

return [{ json: { ...amont,
  transcription_statut: statut,
  transcription_echec: echec,
  transcription_erreur: echec ? (charge?.error?.message || 'transcription indisponible') : null,
  transcript,
  transcription_usage: charge?.usage || null,
  faire_extraction: !!(ex.demandee && !echec),
  llm_corps: {
    provider: ex.provider,
    model: ex.model,
    api_key: ex.api_key,
    max_tokens: ex.max_tokens,
    messages: [{ role: 'user', content: promptFinal }],
  } } }];

const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.query) {
  errors.push('Missing required parameter: query');
}

if (!body.google_api_key) {
  errors.push('Missing required parameter: google_api_key');
}

if (!body.anthropic_api_key && !body.openai_api_key) {
  errors.push('Missing API key: anthropic_api_key or openai_api_key required for recipe extraction');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

const prefs = body.preferences || {};

// Generate job_id if callback_url provided but no job_id
const crypto = require('crypto');
const job_id = body.job_id || (body.callback_url ? crypto.randomUUID() : null);

return [{
  json: {
    valid: true,
    query: body.query,
    google_api_key: body.google_api_key,
    anthropic_api_key: body.anthropic_api_key,
    openai_api_key: body.openai_api_key,
    user_id: body.user_id,
    language: prefs.language || 'fr',
    max_videos: prefs.max_videos || 1,
    prefer_short: prefs.prefer_short || false,
    n8n_webhook_url: process.env.N8N_WEBHOOK_URL || 'http://localhost:5678',
    callback_url: body.callback_url || null,
    job_id: job_id
  }
}];

const input = $input.first().json;

// Store all context needed for async processing
return [{
  json: {
    ...input,
    async_mode: true,
    job_started_at: new Date().toISOString()
  }
}];

const validationData = $('Validate Input').first().json;
const crypto = require('crypto');

const body = {
  success: false,
  job_id: validationData.job_id,
  status: 'failed',
  error: {
    code: 404,
    message: 'No YouTube videos found for query',
    status: 'NOT_FOUND'
  },
  meta: {
    provider: 'youtube',
    query: validationData.query
  }
};

const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callback_url: validationData.callback_url,
    body: body,
    signature: signature
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const video = input.items[0];
const videoId = video.id?.videoId;

return [{
  json: {
    ...prevData,
    video: {
      id: videoId,
      title: video.snippet?.title,
      description: video.snippet?.description,
      channel: video.snippet?.channelTitle,
      thumbnail: video.snippet?.thumbnails?.high?.url || video.snippet?.thumbnails?.default?.url,
      url: `https://www.youtube.com/watch?v=${videoId}`,
      published_at: video.snippet?.publishedAt
    },
    video_url: `https://www.youtube.com/watch?v=${videoId}`
  }
}];

